import math

step = 0
logged = set()

def to_xy(origin, pts):
    ox, oy = origin
    res = []
    for b, d in pts:
        rad = math.radians(b)
        res.append((round(ox + d * math.cos(rad), 1), round(oy + d * math.sin(rad), 2), round(b, 1), round(d, 1)))
    return res

def control(obs):
    global step, logged
    step += 1
    hitch = obs['hitch_deg']
    steer = max(-45.0, min(45.0, 2.5 * hitch))

    # Check left mirror (+64), then right mirror (-64), then left shoulder (+165)
    if step < 12:
        look = 64.0
    elif step < 26:
        look = -64.0
    else:
        look = 165.0

    views = obs.get('views', {})
    if obs['head']['settled']:
        for vname in ('left_mirror', 'right_mirror', 'direct'):
            if vname in views and vname not in logged:
                v = views[vname]
                pts = v.get('walls', [])
                if pts:
                    logged.add(vname + f'_{step//12}')
                    print(f'{vname} (pos={obs["progress"]["covered"]:.1f}m, origin={v["origin"]}):', to_xy(v['origin'], pts))
    return steer, -1.0, look

