import math

state = 'look_left'
left_pts = []
right_pts = []

def control(obs):
    global state, left_pts, right_pts
    gaze = obs['head']['gaze_deg']
    settled = obs['head']['settled']
    views = obs.get('views', {})
    direct = views.get('direct', {})
    walls = direct.get('walls', [])
    corners = direct.get('target_corners', [])

    if state == 'look_left':
        if settled and abs(gaze - 165) < 5 and walls:
            print(f'LEFT (+165): walls={walls[:30]} corners={corners} target={obs.get("target")}')
            state = 'look_right'
            return (0.0, 0.0, -165.0)
        return (0.0, 0.0, 165.0)
    elif state == 'look_right':
        if settled and abs(gaze + 165) < 5 and walls:
            print(f'RIGHT (-165): walls={walls[:30]} corners={corners} target={obs.get("target")}')
            state = 'done'
            wake('scan complete')
            return (0.0, 0.0, -165.0)
        return (0.0, 0.0, -165.0)
    return (0.0, 0.0, -165.0)

